class Solution {
    string chars;
    vector<char> leftChar,rightChar;
    vector<int> length,prefix,suffix,best;
    void pull(int node){
        int a=node*2,b=a+1;
        length[node]=length[a]+length[b];
        leftChar[node]=leftChar[a];
        rightChar[node]=rightChar[b];
        prefix[node]=prefix[a];
        suffix[node]=suffix[b];
        best[node]=max(best[a],best[b]);
        if(rightChar[a]==leftChar[b]){
            best[node]=max(best[node],suffix[a]+prefix[b]);
            if(prefix[a]==length[a])prefix[node]+=prefix[b];
            if(suffix[b]==length[b])suffix[node]+=suffix[a];
        }
    }
    void build(int node,int left,int right){
        if(left==right){
            length[node]=prefix[node]=suffix[node]=best[node]=1;
            leftChar[node]=rightChar[node]=chars[left];
            return;
        }
        int middle=(left+right)/2;
        build(node*2,left,middle);
        build(node*2+1,middle+1,right);
        pull(node);
    }
    void update(int node,int left,int right,int index,char value){
        if(left==right){
            leftChar[node]=rightChar[node]=value;
            return;
        }
        int middle=(left+right)/2;
        if(index<=middle)update(node*2,left,middle,index,value);
        else update(node*2+1,middle+1,right,index,value);
        pull(node);
    }
    public:vector<int> longestRepeating(string s,string queryCharacters,vector<int>& queryIndices){
        chars=s;
        int size=4*s.size();
        leftChar.resize(size);
        rightChar.resize(size);
        length.resize(size);
        prefix.resize(size);
        suffix.resize(size);
        best.resize(size);
        build(1,0,s.size()-1);
        vector<int> answer;
        for(int i=0;i<(int)queryIndices.size();++i){
            update(1,0,s.size()-1,queryIndices[i],queryCharacters[i]);
            answer.push_back(best[1]);
        }
        return answer;
    }
};
